  enabled: u32,
  // Zero after a camera cut, resize, recovery or skipped late phase: every
  // candidate then counts as previously visible and draws early.
  historyValid: u32,
  // Word offsets of the two instance-visibility bit regions in counters.
  previousBase: u32,
  nextBase: u32,
  bitWords: u32,
